const item = $input.first();
let output = item.json.output || item.json.text || item.json;

if (typeof output === 'string') {
  try {
    const clean = output.replace(/```json/gi, '').replace(/```/g, '').trim();
    output = JSON.parse(clean);
  } catch(e) {}
}

if (!Array.isArray(output)) {
  output = [output];
}

return { json: { success: true, resultsCount: output.length, results: output } };
